    for c in df.columns:
        if c in num:
            bad=df[~df[c].str.fullmatch(r'-?\d+(\.\d+)?')]
            if len(bad): print('  bad num',c,len(bad),bad[c].head(3).tolist())
        if 'cnpj' in c:
