txt={a:open(DP+a,encoding='utf-8',errors='replace').read() for a in r.arquivo_origem.unique() if a in files and not a.endswith('xlsx')}
lines={a:t.splitlines() for a,t in txt.items()}
miss=[]
for _,row in r.iterrows():
    a=row.arquivo_origem; ref=row.ref_origem
    if a not in txt: continue
    if re.fullmatch(r'L\d+',ref):
        n=int(ref[1:]); L=lines[a]
        if n<1 or n>len(L): miss.append((a,ref,'linha fora'))
        continue
    for p in ref.split('|'):
        if p not in txt[a]: miss.append((a,p))
print('refs nao encontradas',len(miss),miss[:10])
# aurora lines sample
