aur=la[la.banco=='AURORA']
L=open(DP+'05a_extrato_banco_aurora_cc4471_set2026.csv',encoding='utf-8',errors='replace').read().splitlines()
mm=0
for _,row in aur.iterrows():
    n=int(row.ref_origem[1:]); line=L[n-1]
    v=row.valor.replace('-','')
    if row.descricao[:15] not in line: mm+=1; 
    if mm and mm<3 and row.descricao[:15] not in line: print('AUR mismatch',row.ref_origem,row.descricao,'|',line)
print('aurora desc mismatches',mm,'of',len(aur))
